INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'lens', 'n.', '/lenz/', '(照相机、摄像机的)镜头', 'He looked at the busy street through the lens of his old camera.', '他透过老相机的镜头看着繁忙的街道。', 'Life Behind the Lens', 1, 0, 'senior', 'wordlist', 'elective3', 'U2', 'through the lens', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pose', 'v./n.', '/pəʊz/', '(使)摆好姿势;姿势', 'Every famous person in the city wanted to pose for this quiet photographer.', '城里每个名人都想为这位安静的摄影师摆姿势拍照。', 'Life Behind the Lens', 2, 0, 'senior', 'wordlist', 'elective3', 'U2', 'pose for a photo', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'grocery', 'n.', '/ˈɡrəʊsəri/', '食品杂货店', 'He once photographed a man buying oranges at a small grocery store.', '他曾拍下一个男人在小杂货店买橙子的场景。', 'Life Behind the Lens', 3, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a grocery store', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'fascination', 'n.', '/ˌfæsɪˈneɪʃ(ə)n/', '着迷,迷恋', 'His fascination with what ordinary people wore shaped all of his work.', '他对普通人穿着的着迷塑造了他全部的作品。', 'Life Behind the Lens', 4, 0, 'senior', 'wordlist', 'elective3', 'U2', 'fascination with', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'fashion', 'n.', '/ˈfæʃ(ə)n/', '时尚;流行', 'He believed that fashion belonged to everyone, not only to the rich.', '他相信时尚属于每个人,而不仅属于富人。', 'Life Behind the Lens', 5, 0, 'senior', 'wordlist', 'elective3', 'U2', 'the world of fashion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'uncomplicated', 'adj.', '/ʌnˈkɒmplɪkeɪtɪd/', '不复杂的,简单的;单纯的', 'Although he was world-famous, his approach to life was simple and uncomplicated.', '尽管举世闻名,他对生活的态度却简单而不复杂。', 'Life Behind the Lens', 6, 0, 'senior', 'wordlist', 'elective3', 'U2', 'an uncomplicated life', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'faraway', 'adj.', '/ˈfɑːrəweɪ/', '遥远的', 'He refused free flights to faraway places that others would envy.', '他拒绝了别人会羡慕的、飞往遥远之地的免费机票。', 'Life Behind the Lens', 7, 0, 'senior', 'wordlist', 'elective3', 'U2', 'faraway places', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'celebrity', 'n.', '/sɪˈlebrɪti/', '名人,明星', 'Even at a celebrity party, he was there to work rather than to have fun.', '即使在名人聚会上,他也是去工作而不是去玩乐。', 'Life Behind the Lens', 8, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a celebrity party', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'craft', 'n.', '/krɑːft/', '(某一行业所需的)技能,手艺', 'He stayed focused on his craft and never chased money or fame.', '他专注于自己的手艺,从不追逐金钱或名声。', 'Life Behind the Lens', 9, 0, 'senior', 'wordlist', 'elective3', 'U2', 'stay focused on one''s craft', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'anthropologist', 'n.', '/ˌænθrəˈpɒlədʒɪst/', '人类学家', 'People called him a cultural anthropologist who recorded a whole city''s life.', '人们称他为记录了整座城市生活的文化人类学家。', 'Life Behind the Lens', 10, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a cultural anthropologist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'trial', 'n.', '/ˈtraɪəl/', '试验;尝试', 'She grew the rare plants by much trial and error.', '她经过反复试验才把这些珍稀植物种活。', 'Life Behind the Lens', 11, 0, 'senior', 'wordlist', 'elective3', 'U2', 'by trial and error', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'craftsmanship', 'n.', '/ˈkrɑːftsmənʃɪp/', '手艺;工艺;技艺', 'The spirit of craftsmanship shows in every careful detail of his work.', '匠心精神体现在他作品的每一处用心细节中。', 'Life Behind the Lens', 12, 0, 'senior', 'wordlist', 'elective3', 'U2', 'the spirit of craftsmanship', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'acclaim', 'n.', '/əˈkleɪm/', '表扬,赞赏', 'His skill at his work had already won him wide acclaim.', '他在工作上的技艺早已为他赢得了广泛赞誉。', 'Life Behind the Lens', 13, 0, 'senior', 'wordlist', 'elective3', 'U2', 'win acclaim', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'shun', 'v.', '/ʃʌn/', '(故意)避开,躲开', 'He sought no fame and chose to shun the spotlight all his life.', '他不求名声,一生都选择避开聚光灯。', 'Life Behind the Lens', 14, 0, 'senior', 'wordlist', 'elective3', 'U2', 'shun the spotlight', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'spotlight', 'n.', '/ˈspɒtlaɪt/', '聚光灯;媒体的关注', 'Although famous, he always preferred to stay out of the spotlight.', '尽管出名,他始终更愿待在聚光灯之外。', 'Life Behind the Lens', 15, 0, 'senior', 'wordlist', 'elective3', 'U2', 'out of the spotlight', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'harsh', 'adj.', '/hɑːʃ/', '恶劣的,艰苦的,严峻的', 'The scientists kept working under harsh desert conditions for years.', '科学家们在恶劣的沙漠条件下持续工作了多年。', 'Life Behind the Lens', 16, 0, 'senior', 'wordlist', 'elective3', 'U2', 'harsh conditions', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'prosperous', 'adj.', '/ˈprɒspərəs/', '富裕的,繁荣的,兴旺的', 'Their efforts helped build a stronger and more prosperous country.', '他们的努力帮助建设了一个更强大、更繁荣的国家。', 'Life Behind the Lens', 17, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a prosperous country', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'courtyard', 'n.', '/ˈkɔːtjɑːd/', '庭院,院子', 'In the quiet courtyard, time seemed to move at its own pace.', '在安静的庭院里,时间仿佛按自己的节奏流动。', 'Life Behind the Lens', 18, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a quiet courtyard', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'precious', 'adj.', '/ˈpreʃəs/', '珍稀的;贵重的', 'These masters have spent their lives restoring precious antiques.', '这些大师们用一生修复珍贵的古董。', 'Life Behind the Lens', 19, 0, 'senior', 'wordlist', 'elective3', 'U2', 'precious antiques', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'antique', 'n.', '/ˌænˈtiːk/', '古董,古玩,古物', 'Wang Jin repairs antique clocks that are hundreds of years old.', '王津修复着已有数百年历史的古董钟表。', 'Life Behind the Lens', 20, 0, 'senior', 'wordlist', 'elective3', 'U2', 'an antique clock', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'restoration', 'n.', '/ˌrestəˈreɪʃ(ə)n/', '(旧物等的)修复,整修', 'Each timepiece needs its own careful method of restoration.', '每件计时器都需要自己独特而细致的修复方法。', 'Life Behind the Lens', 21, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a method of restoration', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'crimson', 'adj.', '/ˈkrɪmz(ə)n/', '深红色的', 'He walked through the seven crimson gates to reach his workshop.', '他穿过七道深红色的大门来到自己的工作室。', 'Life Behind the Lens', 22, 0, 'senior', 'wordlist', 'elective3', 'U2', 'crimson gates', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'workplace', 'n.', '/ˈwɜːkpleɪs/', '工作场所', 'Admirers often stop him on the way to his workplace for a photo.', '仰慕者常在他去工作场所的路上拦住他合影。', 'Life Behind the Lens', 23, 0, 'senior', 'wordlist', 'elective3', 'U2', 'on the way to the workplace', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'timepiece', 'n.', '/ˈtaɪmpiːs/', '计时器;钟;表', 'The museum holds one of the finest collections of timepieces in the world.', '这座博物馆收藏着世界上最精美的计时器藏品之一。', 'Life Behind the Lens', 24, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a collection of timepieces', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'envoy', 'n.', '/ˈenvɔɪ/', '使者,使节', 'Foreign envoys once presented these emperors with splendid clocks.', '外国使节曾向这些皇帝进献华丽的钟表。', 'Life Behind the Lens', 25, 0, 'senior', 'wordlist', 'elective3', 'U2', 'foreign envoys', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'intricate', 'adj.', '/ˈɪntrɪkət/', '错综复杂的', 'The intricate clock has thousands of tiny moving parts inside it.', '这座错综复杂的钟内部有成千上万个微小的活动部件。', 'Life Behind the Lens', 26, 0, 'senior', 'wordlist', 'elective3', 'U2', 'an intricate clock', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'maximum', 'n.', '/ˈmæksɪməm/', '最大量,最大值', 'Each expert can repair a maximum of two large pieces a year.', '每位专家一年最多只能修复两件大型作品。', 'Life Behind the Lens', 27, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a maximum of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'painstaking', 'adj.', '/ˈpeɪnzteɪkɪŋ/', '小心的;费尽心思的;精心的', 'Through their painstaking efforts, the old clocks slowly come back to life.', '通过他们精心的努力,旧钟表慢慢恢复了生机。', 'Life Behind the Lens', 28, 0, 'senior', 'wordlist', 'elective3', 'U2', 'painstaking efforts', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'workshop', 'n.', '/ˈwɜːkʃɒp/', '车间,工作室', 'The only sound in his workshop is the chiming of repaired clocks.', '他工作室里唯一的声音是修好的钟表的报时声。', 'Life Behind the Lens', 29, 0, 'senior', 'wordlist', 'elective3', 'U2', 'in the workshop', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'melody', 'n.', '/ˈmelədi/', '歌曲;曲调', 'To him, the chiming melody of the clocks is the best music in the world.', '对他来说,钟表报时的曲调是世界上最美的音乐。', 'Life Behind the Lens', 30, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a chiming melody', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'polish', 'v.', '/ˈpɒlɪʃ/', '擦亮,擦光', 'He carefully cleaned and polished every part of the old clock.', '他仔细地清洁并擦亮了旧钟的每一个部件。', 'Life Behind the Lens', 31, 0, 'senior', 'wordlist', 'elective3', 'U2', 'polish each part', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'gigantic', 'adj.', '/dʒaɪˈɡæntɪk/', '巨大的,庞大的', 'At last he wound up the gigantic clocks from the time of Qianlong.', '最后他给乾隆时期的巨型钟表上紧了发条。', 'Life Behind the Lens', 32, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a gigantic clock', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bark', 'v.', '/bɑːk/', '(狗)吠叫', 'When the clock comes to life, tiny model dogs bark and birds flap their wings.', '当钟表运转起来,小小的模型狗会吠叫,鸟儿会扑动翅膀。', 'Life Behind the Lens', 33, 0, 'senior', 'wordlist', 'elective3', 'U2', 'dogs bark', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'spin', 'v.', '/spɪn/', '旋转;纺(线)', 'On the old clock, a little figure of a woman begins to spin.', '在那座旧钟上,一个小小的女子塑像开始旋转。', 'Life Behind the Lens', 34, 0, 'senior', 'wordlist', 'elective3', 'U2', 'begin to spin', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'exaggeration', 'n.', '/ɪɡˌzædʒəˈreɪʃ(ə)n/', '夸大,夸张', 'Saying that these antiques have lives is no exaggeration at all.', '说这些古董有生命绝非夸张。', 'Life Behind the Lens', 35, 0, 'senior', 'wordlist', 'elective3', 'U2', 'no exaggeration', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'metaphor', 'n.', '/ˈmetəfə/', '隐喻,暗喻', 'He used a metaphor to describe how the old clocks seem alive.', '他用一个隐喻来描述旧钟表如何仿佛是活的。', 'Life Behind the Lens', 36, 0, 'senior', 'wordlist', 'elective3', 'U2', 'use a metaphor', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'nonetheless', 'adv.', '/ˌnʌnðəˈles/', '然而;尽管如此', 'The work may never be finished; nonetheless, he remains hopeful.', '这项工作也许永远做不完;尽管如此,他依然满怀希望。', 'Life Behind the Lens', 37, 0, 'senior', 'wordlist', 'elective3', 'U2', 'nonetheless', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'artisan', 'n.', '/ˌɑːtɪˈzæn/', '工匠,手艺人', 'A new generation of artisans will carry the craft into the future.', '新一代工匠将把这门手艺带向未来。', 'Life Behind the Lens', 38, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a young artisan', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'preserve', 'v.', '/prɪˈzɜːv/', '维护,保护;保存', 'Their work helps preserve traditional skills for the future.', '他们的工作有助于为未来保存传统技艺。', 'Life Behind the Lens', 39, 0, 'senior', 'wordlist', 'elective3', 'U2', 'preserve traditional skills', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'apt', 'adj.', '/æpt/', '适当的,恰当的', 'In our fast world, the saying "time waits for no man" seems very apt.', '在我们快节奏的世界里,"时不待人"这句话显得格外恰当。', 'Life Behind the Lens', 40, 0, 'senior', 'wordlist', 'elective3', 'U2', 'seem apt', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'timeless', 'adj.', '/ˈtaɪmləs/', '永恒的,恒久的;永不过时的', 'There is something timeless about the way these masters work.', '这些大师工作的方式中有一种永恒的东西。', 'Life Behind the Lens', 41, 0, 'senior', 'wordlist', 'elective3', 'U2', 'something timeless', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'modest', 'adj.', '/ˈmɒdɪst/', '谦虚的,谦逊的', 'They piece together the past with skilful hands and modest hearts.', '他们用灵巧的双手和谦逊的心拼接起过去。', 'Life Behind the Lens', 42, 0, 'senior', 'wordlist', 'elective3', 'U2', 'modest hearts', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'essay', 'n.', '/ˈeseɪ/', '短文,论说文', 'She wrote an expository essay about a famous craftworker.', '她写了一篇关于一位著名手艺人的说明文。', 'Life Behind the Lens', 43, 0, 'senior', 'wordlist', 'elective3', 'U2', 'an expository essay', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'dominate', 'v.', '/ˈdɒmɪneɪt/', '支配,控制,主宰', 'For seven generations, the Lei family came to dominate imperial building.', '七代人间,雷氏家族逐渐主宰了皇家建筑。', 'Life Behind the Lens', 44, 0, 'senior', 'wordlist', 'elective3', 'U2', 'dominate the field', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'architecture', 'n.', '/ˈɑːkɪtektʃə/', '建筑风格,建筑设计', 'Their work in architecture ranged from grand halls to roads and dams.', '他们在建筑上的作品从宏伟的殿堂到道路和水坝无所不包。', 'Life Behind the Lens', 45, 0, 'senior', 'wordlist', 'elective3', 'U2', 'imperial architecture', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'ambitious', 'adj.', '/æmˈbɪʃəs/', '宏大的,艰巨的;有抱负的', 'Each generation took on ambitious projects that lasted for years.', '每一代人都承担了历时数年的宏大工程。', 'Life Behind the Lens', 46, 0, 'senior', 'wordlist', 'elective3', 'U2', 'ambitious projects', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'associate', 'v.', '/əˈsəʊʃieɪt/', '把……联系起来;与……有关', 'People still associate these great works with the court rather than the family.', '人们仍把这些伟大作品与朝廷而非这个家族联系在一起。', 'Life Behind the Lens', 47, 0, 'senior', 'wordlist', 'elective3', 'U2', 'associate with', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'comprise', 'v.', '/kəmˈpraɪz/', '包括,由……构成', 'The main body of the essay comprises facts and supporting evidence.', '这篇文章的主体由事实和支撑性证据构成。', 'Life Behind the Lens', 48, 0, 'senior', 'wordlist', 'elective3', 'U2', 'comprise of facts', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u2.01', '①what / that 引导表语从句', 'A2', 12, '外研社版选择性必修第三册 U2 — 系动词 be 后接表语从句:从句缺主语或宾语时用 what(在从句中充当成分);从句结构完整、不缺成分时用 that(只起连接作用)。', 1, 'elective3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u2.02', '②why / where / how / when 引导表语从句', 'A2', 12, '外研社版选择性必修第三册 U2 — be 后的表语从句缺状语时,按意义选关系副词:缺原因用 why,缺地点用 where,缺方式/手段用 how,缺时间用 when。', 2, 'elective3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u2.03', '③because / whether 引导表语从句 与「the reason is THAT」陷阱', 'A2', 12, '外研社版选择性必修第三册 U2 — 「This is ____」后接原因从句用 because;「The reason … is ____」后只能用 that(不能用 because);表是非选择用 whether。', 3, 'elective3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"Hard work and devotion are ____ made Bill Cunningham so special."', 'what', 'that', 'which', 'why', 'A', 'be 后的从句缺主语,连接词要在从句里作主语 → what。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"A good photo is often ____ an ordinary person is wearing on the street."', 'that', 'what', 'how', 'which', 'B', '从句中 wearing 缺宾语,连接词作宾语 → what。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"His simple cameras were ____ he used to capture the whole city."', 'that', 'which', 'what', 'where', 'C', '从句中 used 缺宾语,连接词作宾语 → what。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"Honesty was ____ this photographer valued most in his life."', 'that', 'why', 'which', 'what', 'D', '从句中 valued 缺宾语,连接词作宾语 → what。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"Real street scenes were ____ gave his pictures their power."', 'what', 'that', 'which', 'how', 'A', '从句缺主语,连接词作主语 → what。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"Freedom, he said, is ____ matters far more than money."', 'that', 'what', 'why', 'which', 'B', '从句缺主语,连接词作主语 → what。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"The faces of strangers were ____ he loved to photograph most."', 'that', 'which', 'what', 'where', 'C', '从句中 photograph 缺宾语,连接词作宾语 → what。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"Curiosity about people is ____ keeps a great photographer going."', 'that', 'how', 'which', 'what', 'D', '从句缺主语,连接词作主语 → what。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"Old clocks are ____ these masters spend their lives bringing back to life."', 'what', 'that', 'which', 'where', 'A', '从句中 bringing 缺宾语,连接词作宾语 → what。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"Patience is ____ every young artisan must learn first of all."', 'that', 'what', 'how', 'which', 'B', '从句中 learn 缺宾语,连接词作宾语 → what。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"The simple truth is ____ he never took a single day off."', 'what', 'why', 'that', 'which', 'C', '从句结构完整、不缺成分,连接词只起连接作用 → that。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"The fact is ____ he photographed the poor as gladly as the rich."', 'what', 'which', 'how', 'that', 'D', '从句完整不缺成分 → that。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"His firm belief was ____ beauty could be found in everyday scenes."', 'that', 'what', 'why', 'which', 'A', '从句完整不缺成分 → that。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"The problem today is ____ very few people still repair antique clocks."', 'what', 'that', 'which', 'how', 'B', '从句完整不缺成分 → that。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"One good thing about his work is ____ it recorded a whole city''s life."', 'what', 'why', 'that', 'which', 'C', '从句完整不缺成分 → that。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"The point of the documentary is ____ these masters deserve our respect."', 'what', 'which', 'how', 'that', 'D', '从句完整不缺成分 → that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"What surprised me most was ____ he lived in such a small apartment."', 'that', 'what', 'why', 'which', 'A', 'be 后从句完整不缺成分,连接词只起连接作用 → that。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"The truth about the old clocks is ____ each one needs its own method."', 'what', 'that', 'which', 'how', 'B', '从句完整不缺成分 → that。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"My first impression was ____ the workshop was almost completely silent."', 'what', 'why', 'that', 'which', 'C', '从句完整不缺成分 → that。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.01'), '"The wonderful thing is ____ the repaired clocks seem to come alive again."', 'what', 'which', 'how', 'that', 'D', '从句完整不缺成分 → that。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"His complete devotion is ____ Bill Cunningham is still admired by so many."', 'why', 'where', 'how', 'when', 'A', '从句表「受人敬佩」的原因,缺原因状语 → why。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"His honesty is ____ no gift could ever change his mind."', 'where', 'why', 'how', 'when', 'B', '从句说明结果背后的原因,缺原因状语 → why。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"Years of silence and focus are ____ his photos feel so calm."', 'where', 'how', 'why', 'when', 'C', '从句表照片如此沉静的原因 → why。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"Their deep love of tradition is ____ these crafts have not died out."', 'where', 'how', 'when', 'why', 'D', '从句表手艺得以存续的原因 → why。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"A single act of kindness is ____ the old man is still remembered in the town."', 'why', 'where', 'how', 'when', 'A', '从句表他被铭记的原因 → why。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"A small restaurant was ____ he ate the same breakfast every single day."', 'why', 'where', 'how', 'when', 'B', '从句缺地点状语(在某处吃饭) → where。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"The quiet courtyard is ____ the clock masters do their patient work."', 'why', 'how', 'where', 'when', 'C', '从句缺地点状语 → where。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"The busy streets of New York were ____ he took most of his pictures."', 'why', 'how', 'when', 'where', 'D', '从句缺地点状语 → where。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"A tiny workshop is ____ these precious timepieces are brought back to life."', 'where', 'why', 'how', 'when', 'A', '从句缺地点状语 → where。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"The Palace Museum is ____ thousands of antique clocks are carefully kept."', 'why', 'where', 'how', 'when', 'B', '从句缺地点状语 → where。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"Hours of daily practice are ____ a young artisan slowly masters the craft."', 'why', 'where', 'how', 'when', 'C', '从句说明掌握手艺的方式/途径,缺方式状语 → how。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"Gentle hands and great care are ____ the broken clocks are repaired."', 'why', 'where', 'when', 'how', 'D', '从句说明修钟的方式,缺方式状语 → how。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"Watching strangers on the street is ____ he discovered his best subjects."', 'how', 'why', 'where', 'when', 'A', '从句说明他发现题材的方式 → how。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"Going out in every kind of weather is ____ he captured the real city."', 'why', 'how', 'where', 'when', 'B', '从句说明他拍到真实城市的方式 → how。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"Following his old teacher step by step is ____ Wang Jin learned to fix clocks."', 'why', 'where', 'how', 'when', 'C', '从句说明他学修钟的方式 → how。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"Early dawn was ____ the soft light was best for taking photos."', 'why', 'where', 'how', 'when', 'D', '从句缺时间状语(在某时光线最好) → when。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"The moment the clock chimes is ____ Wang Jin feels most rewarded."', 'when', 'why', 'where', 'how', 'A', '从句缺时间状语 → when。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"Early spring is ____ the museum receives the most visitors each year."', 'why', 'when', 'where', 'how', 'B', '从句缺时间状语 → when。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"The day of the exhibition was ____ his work was finally seen by everyone."', 'why', 'where', 'when', 'how', 'C', '从句缺时间状语 → when。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.02'), '"Late evening was ____ he returned home after a long day on the streets."', 'why', 'where', 'how', 'when', 'D', '从句缺时间状语 → when。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"The reason his photos look so alive is ____ he always shot real people."', 'that', 'because', 'why', 'what', 'A', '「The reason … is ____」后只能用 that,不能用 because。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"The reason the old man is still remembered is ____ he never chased fame."', 'because', 'that', 'what', 'which', 'B', '「The reason … is ____」后用 that,不用 because。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"One reason these clocks survive is ____ the masters check them again and again."', 'because', 'why', 'that', 'what', 'C', '「reason … is ____」后用 that。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"The main reason he refused gifts is ____ he wanted to keep his freedom."', 'because', 'what', 'which', 'that', 'D', '「reason … is ____」后用 that,不用 because。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"The reason the workshop is so quiet is ____ everyone there is fully focused."', 'that', 'because', 'why', 'what', 'A', '「reason … is ____」后用 that。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"A big reason the craft nearly died out is ____ few young people would learn it."', 'because', 'that', 'what', 'which', 'B', '「reason … is ____」后用 that。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"The reason his pictures still matter is ____ they recorded a whole city''s life."', 'because', 'why', 'that', 'what', 'C', '「reason … is ____」后用 that。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"The real question is ____ the broken clock can be repaired at all."', 'because', 'that', 'if', 'whether', 'D', '表「能否」的是非选择作表语用 whether;表语从句不用 if。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"What worried the team was ____ the old camera was still worth fixing."', 'whether', 'because', 'if', 'that', 'A', '表「是否值得」的是非意义 → whether。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"The first thing to decide is ____ the antique is genuine or just a copy."', 'because', 'whether', 'that', 'if', 'B', '有 or 表示是非选择,表语从句用 whether。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"The hardest choice was ____ he should keep the photo or delete it."', 'because', 'if', 'whether', 'why', 'C', '表是非选择(留还是删) → whether。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"The question for every artisan is ____ speed or quality matters more."', 'because', 'that', 'if', 'whether', 'D', '表是非选择 → whether。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"What the judges discussed was ____ the young photographer deserved the prize."', 'whether', 'because', 'if', 'that', 'A', '表「是否应得」的是非意义 → whether。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"He never won a prize. This is ____ he turned down every award offered to him."', 'that', 'because', 'why', 'what', 'B', '「This is ____」后接原因从句(他拒奖是没得奖的原因) → because。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"His photos feel so honest. This is ____ he never told people how to pose."', 'that', 'why', 'because', 'what', 'C', '「This is ____」后接原因从句 → because。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"The clocks sound perfect again. This is ____ Wang Jin polished every tiny part."', 'that', 'why', 'which', 'because', 'D', '「This is ____」后接原因从句 → because。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"Few artisans are left today. This is ____ the work takes years to master."', 'because', 'that', 'why', 'what', 'A', '「This is ____」后接原因从句 → because。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"People trusted him completely. This is ____ he refused every free gift."', 'that', 'because', 'why', 'which', 'B', '「This is ____」后接原因从句 → because。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"The museum feels timeless. This is ____ its masters work slowly and with care."', 'that', 'why', 'because', 'what', 'C', '「This is ____」后接原因从句 → because。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U2' AND code='fe3u2.03'), '"The only reason he went to the celebrity party is ____ he wanted to work, not relax."', 'because', 'what', 'which', 'that', 'D', '「The reason … is ____」后只能用 that,不能用 because。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Man on the Bicycle', 'For more than fifty years, a white-haired man rode an old bicycle around New York, always in the same plain blue jacket. Few people guessed that this simple figure was Bill Cunningham, one of the most important photographers of his time. He never used expensive cameras or worked in a comfortable studio. Instead, he went out onto the streets every single day, whatever the weather, and photographed ordinary people as gladly as famous ones. What interested him was not who people were, but what they were wearing. He hardly ever took a day off and never stayed home sick. He lived in a tiny flat and refused the free clothes and flights that others offered him, for he wanted above all to keep his freedom. To him, money was the cheapest thing of all. Through years of quiet, patient work, he recorded the life of a whole city.', '人物·街头摄影师 Bill Cunningham', 148, '[{"q":"Why did few people recognise Bill Cunningham on the street?","answer":"A","options":["He looked plain and dressed very simply.","He hid his face behind a large camera.","He only went out late at night.","He rarely left his small apartment."],"explanation":"由 ''a white-haired man … in the same plain blue jacket'' 和 ''this simple figure'' 转述;他外表朴素,故无人认出。"},{"q":"What did Cunningham care about most when taking photos?","answer":"B","options":["The most expensive cameras he could buy.","The clothes people were wearing rather than their fame.","Only the richest and most famous people.","Photos taken inside a warm studio."],"explanation":"由 ''not who people were, but what they were wearing'' 转述。"},{"q":"Why did he turn down free clothes and flights?","answer":"A","options":["He wanted to protect his own independence.","He already owned too many clothes.","He disliked travelling abroad.","He thought the gifts were of poor quality."],"explanation":"由 ''he wanted above all to keep his freedom'' 转述。"}]'::jsonb, '[{"word":"studio","cn":"摄影棚;工作室"},{"word":"ordinary","cn":"普通的"}]'::jsonb, 2, 'elective3', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Master of the Clocks', 'Behind the high red walls of the Forbidden City, in a quiet courtyard, a master named Wang Jin spends his days repairing antique clocks. Many of these timepieces are hundreds of years old and were once given to Qing emperors by foreign envoys. Each clock is different, so each one needs its own method of restoration. Because the work is so delicate and the right materials are hard to find, a single expert can finish only two large pieces in a whole year. For a long time, Wang Jin and one student were the only people doing this work. Yet he never hurries. When a repaired clock finally sounds again, water seems to flow and tiny birds appear to move. To Wang Jin, that sound is the most beautiful music in the world. Now he is training younger workers, hoping the ancient skill will live on.', '人物·故宫钟表修复师 王津', 146, '[{"q":"Why can each expert repair only a few clocks each year?","answer":"B","options":["The experts are lazy and often rest.","The work is delicate and proper materials are scarce.","The clocks are too cheap to bother with.","The museum only opens for a short season."],"explanation":"由 ''the work is so delicate and the right materials are hard to find'' 转述。"},{"q":"What makes Wang Jin feel most rewarded in his job?","answer":"C","options":["Being stopped by admirers for photographs.","Finishing as many clocks as possible quickly.","Hearing a clock he has mended sound once more.","Receiving gifts from foreign envoys."],"explanation":"由 ''When a repaired clock finally sounds again … the most beautiful music in the world'' 转述。"},{"q":"Why is Wang Jin training younger workers?","answer":"D","options":["Because he plans to stop working at once.","Because the museum forced him to do so.","To make the repairs go much faster.","To keep the old craft alive for later generations."],"explanation":"由 ''hoping the ancient skill will live on'' 转述。"}]'::jsonb, '[{"word":"delicate","cn":"精细的;易损的"},{"word":"emperor","cn":"皇帝"}]'::jsonb, 2, 'elective3', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Seven Generations of Builders', 'What do the Summer Palace and many other royal wonders have in common? They were all built by one remarkable family, the Lei family. For seven generations, this family quietly led imperial building in China. Their designs ranged from grand halls to roads and dams, and their skill was so great that many of their buildings survived earthquakes and stood for hundreds of years. The Lei family were careful engineers too. They drew detailed plans and made small models of their projects, and a number of these models still exist today. Yet they never sought fame. Even now, their great works are linked more with the royal court than with the family name. Together with their talent, they showed hard work and humility. Their story reminds us that true craft is a treasure which can last far beyond a single lifetime.', '人物·皇家建筑世家 雷氏家族', 141, '[{"q":"What was special about the buildings the Lei family designed?","answer":"A","options":["Many lasted for centuries and survived earthquakes.","They were all rebuilt every few years.","They were made only of paper and wood.","None of them has survived to today."],"explanation":"由 ''survived earthquakes and stood for hundreds of years'' 转述。"},{"q":"Why are the Lei family not widely known today?","answer":"B","options":["They built only small, plain houses.","They never looked for fame for themselves.","They kept all their plans a secret.","They lived a very short time ago."],"explanation":"由 ''they never sought fame'' 转述。"},{"q":"What lesson does the passage draw from their story?","answer":"C","options":["Only the rich can build lasting works.","Fame is the true reward for hard work.","Fine craftsmanship can outlast the people who create it.","Old buildings should always be replaced."],"explanation":"由 ''true craft is a treasure which can last far beyond a single lifetime'' 转述。"}]'::jsonb, '[{"word":"humility","cn":"谦逊"},{"word":"model","cn":"模型"}]'::jsonb, 2, 'elective3', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Lifetime on the Stage', 'Mei Lanfang was born in 1894 into a family of opera performers. At the age of eight he began training in Peking Opera every day. When he was seventeen, he kept a flock of pigeons and trained them to fly high. Each day he watched them as they moved across the sky, and this slowly helped him develop the expressive eye movements that became so important to his art. His hard work and dedication made him a leading performer. Mei was also a bold innovator. Besides new stage designs and singing styles, his fresh ideas in make-up and costume allowed female characters to be shown more vividly. This added greatly to the growth of Peking Opera. Until he passed away in 1961, Mei had spent almost sixty years performing and helping the art form spread. His lifelong devotion made him one of the most celebrated opera artists ever.', '人物·京剧艺术家 梅兰芳', 148, '[{"q":"How did watching his pigeons help Mei Lanfang?","answer":"D","options":["It taught him how to sing more loudly.","It gave him ideas for new stage lights.","It helped him relax after long shows.","It trained the expressive eye movements his art needed."],"explanation":"由 ''helped him develop the expressive eye movements that became so important to his art'' 转述。"},{"q":"What did Mei Lanfang change about Peking Opera?","answer":"A","options":["He brought fresh ideas to make-up and costume.","He removed all female characters from it.","He made every show much shorter.","He stopped using any music at all."],"explanation":"由 ''his fresh ideas in make-up and costume allowed female characters to be shown more vividly'' 转述。"},{"q":"What does the passage say made him so celebrated?","answer":"B","options":["His large family of performers.","His devotion to the art over many decades.","The single role he played as a child.","His habit of keeping many pigeons."],"explanation":"由 ''His lifelong devotion made him one of the most celebrated opera artists ever'' 转述。"}]'::jsonb, '[{"word":"innovator","cn":"革新者"},{"word":"costume","cn":"戏服;服装"}]'::jsonb, 2, 'elective3', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Why Handmade Still Matters', 'For many years, traditional crafts have been disappearing from countries all over the world. As more and more skills are lost forever, people are beginning to understand how important it is to protect the ones that remain. In fact, after a long decline, many old crafts are now enjoying a fresh start. There is greater public interest in old stories and customs, as well as a wish for high-quality, handmade goods. Such objects are made through a mix of skill, respect for materials, devotion to tradition, and full attention to the task. Craftsmanship answers a deep human need for work that is skilled and socially useful, the kind of work that others can admire and value. When we buy something made by hand, we are not only paying for an object. We are also helping to keep alive the knowledge and care that machines can never fully copy.', '议论·匠心精神与手工艺复兴', 148, '[{"q":"Why are people now paying more attention to old crafts?","answer":"C","options":["Handmade goods have become much cheaper.","Machines can now copy any craft perfectly.","Many skills have been lost, so they want to save the rest.","The crafts are no longer hard to learn."],"explanation":"由 ''more and more skills are lost forever … protect the ones that remain'' 转述。"},{"q":"According to the passage, how are fine handmade objects produced?","answer":"D","options":["By working as fast as a machine can.","By using the cheapest possible materials.","By copying older finished products exactly.","By combining skill, respect for materials and full focus."],"explanation":"由 ''a mix of skill, respect for materials, devotion to tradition, and full attention'' 转述。"},{"q":"What extra value do we support when buying handmade goods?","answer":"A","options":["We help preserve knowledge and care machines cannot copy.","We make the objects last for only a season.","We lower the price of all factory goods.","We help machines learn the same skills."],"explanation":"由 ''helping to keep alive the knowledge and care that machines can never fully copy'' 转述。"}]'::jsonb, '[{"word":"decline","cn":"衰落"},{"word":"handmade","cn":"手工制作的"}]'::jsonb, 2, 'elective3', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Learning to See', 'Lin had always loved taking pictures, but she knew she still had much to learn. So she asked a retired news photographer named Mr Zhou to teach her. On her first day, he did not let her touch a camera at all. Instead, he told her to sit on a busy corner and simply watch people for two hours. "A good photographer is first of all a careful observer," he said. At first Lin felt bored, yet slowly she began to notice small, lovely moments: an old man feeding birds, two children sharing an umbrella. Over the next months, Mr Zhou taught her how light, patience and timing matter far more than expensive equipment. He often reminded her that the best photos come from real life, not from a studio. By the end of the year, Lin understood that learning to see was the true heart of her craft.', '记叙·年轻摄影学徒的第一课', 149, '[{"q":"Why did Mr Zhou tell Lin to watch people on her first day?","answer":"B","options":["He had no camera for her to use that day.","He wanted her to learn to observe carefully first.","He thought she already knew enough.","He wanted her to find new customers."],"explanation":"由 ''A good photographer is first of all a careful observer'' 转述。"},{"q":"What did Mr Zhou say mattered more than costly equipment?","answer":"C","options":["A large and comfortable studio.","Famous and willing models.","Light, patience and a good sense of timing.","The newest kind of camera."],"explanation":"由 ''light, patience and timing matter far more than expensive equipment'' 转述。"},{"q":"What did Lin finally understand about her craft?","answer":"D","options":["That only luck makes a great photo.","That a studio is the most important thing.","That equipment decides everything.","That truly seeing the world lies at its heart."],"explanation":"由 ''learning to see was the true heart of her craft'' 转述。"}]'::jsonb, '[{"word":"observer","cn":"观察者"},{"word":"timing","cn":"时机的把握"}]'::jsonb, 2, 'elective3', 'U2', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U2', 'Joining the Photography Club', 'Last autumn I joined the school photography (1)____. At the first meeting, our teacher said that a camera is only a (2)____; the real art lies in how you look at the world. She asked us not to (3)____ about expensive equipment, but to practise every day with whatever we had. My first photos were (4)____ — blurred, dark and badly framed. Yet I did not give (5)____. Slowly I learned to wait for the right (6)____, when the sun was low and soft. I also began to (7)____ ordinary scenes that I had never paid attention to before, such as an old woman selling flowers. My teacher often (8)____ us that patience matters more than luck. By winter, my pictures had clearly (9)____, and I felt proud of every small (10)____ I had made.', 135, 2, '[{"q":"1","answer":"A","options":["club","price","river","key"],"explanation":"join the photography club 加入摄影社。"},{"q":"2","answer":"B","options":["prize","tool","noise","season"],"explanation":"a camera is only a tool 相机只是工具。"},{"q":"3","answer":"C","options":["sing","drive","worry","sleep"],"explanation":"not to worry about equipment 不必担心器材。"},{"q":"4","answer":"D","options":["perfect","golden","polite","terrible"],"explanation":"blurred, dark → terrible 很糟糕。"},{"q":"5","answer":"A","options":["up","out","down","back"],"explanation":"give up 放弃。"},{"q":"6","answer":"B","options":["ticket","moment","garden","answer"],"explanation":"the right moment 合适的时机。"},{"q":"7","answer":"C","options":["throw","buy","notice","cook"],"explanation":"begin to notice scenes 开始注意到景象。"},{"q":"8","answer":"D","options":["allowed","forced","feared","reminded"],"explanation":"remind sb that … 提醒某人……。"},{"q":"9","answer":"A","options":["improved","fallen","stopped","ended"],"explanation":"pictures had improved 照片有了进步。"},{"q":"10","answer":"B","options":["noise","step","price","garden"],"explanation":"every small step 每一小步进步。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U2', 'Grandfather''s Pocket Watch', 'My grandfather kept an old pocket (1)____ that had stopped working years ago. One winter evening, he decided to (2)____ it himself at the kitchen table. He opened the tiny back cover and looked at the (3)____ wheels inside with a magnifying glass. "Each part must be cleaned with great (4)____," he told me softly. For hours he worked, his hands moving slowly and (5)____. I was amazed that he never lost his (6)____, even when a spring jumped out and rolled across the floor. At last he (7)____ the cover and gently wound it. To my (8)____, the old watch began to tick again. Grandfather smiled and said that fixing it was like bringing a small friend back to (9)____. That night I learned that (10)____ and care can repair almost anything.', 133, 2, '[{"q":"1","answer":"C","options":["river","ticket","watch","road"],"explanation":"a pocket watch 怀表。"},{"q":"2","answer":"D","options":["sell","throw","paint","repair"],"explanation":"repair it himself 自己修。"},{"q":"3","answer":"A","options":["tiny","loud","sweet","warm"],"explanation":"the tiny wheels 细小的齿轮。"},{"q":"4","answer":"B","options":["noise","care","speed","luck"],"explanation":"with great care 非常小心地。"},{"q":"5","answer":"C","options":["loudly","quickly","carefully","angrily"],"explanation":"slowly and carefully 缓慢而仔细。"},{"q":"6","answer":"D","options":["ticket","money","voice","patience"],"explanation":"lost his patience 失去耐心。"},{"q":"7","answer":"A","options":["closed","opened","broke","lost"],"explanation":"closed the cover 合上盖子。"},{"q":"8","answer":"B","options":["garden","surprise","price","lesson"],"explanation":"to my surprise 令我惊讶的是。"},{"q":"9","answer":"C","options":["school","work","life","town"],"explanation":"back to life 恢复生机。"},{"q":"10","answer":"D","options":["noise","money","luck","effort"],"explanation":"effort and care 努力与用心。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U2', 'Learning Calligraphy', 'When I was ten, my mother sent me to learn Chinese (1)____. My first teacher was a patient old man who wrote beautiful characters with a soft (2)____. He told me that good writing needs a calm (3)____ and a steady hand. At first my lines were (4)____ and ugly, and I wanted to quit. But the teacher asked me to (5)____ the same stroke again and again until it felt natural. "Skill grows through (6)____ and error," he often said. Day by day, my characters slowly became more (7)____. I learned to sit up straight, breathe slowly, and (8)____ fully on each line. After two years, I could write a whole poem that I was (9)____ of. Looking back, I see that calligraphy taught me not only to write, but also to be (10)____.', 135, 2, '[{"q":"1","answer":"A","options":["calligraphy","football","cooking","swimming"],"explanation":"learn Chinese calligraphy 学书法。"},{"q":"2","answer":"B","options":["stone","brush","glass","rope"],"explanation":"wrote with a soft brush 用软毛笔写。"},{"q":"3","answer":"C","options":["noise","price","mind","road"],"explanation":"a calm mind 平静的心。"},{"q":"4","answer":"D","options":["perfect","golden","polite","messy"],"explanation":"messy and ugly 凌乱难看。"},{"q":"5","answer":"A","options":["repeat","sell","throw","buy"],"explanation":"repeat the same stroke 重复同一笔画。"},{"q":"6","answer":"B","options":["music","trial","garden","price"],"explanation":"through trial and error 反复试验。"},{"q":"7","answer":"C","options":["terrible","empty","beautiful","loud"],"explanation":"became more beautiful 越来越美。"},{"q":"8","answer":"D","options":["jump","shout","sleep","focus"],"explanation":"focus on each line 专注于每一行。"},{"q":"9","answer":"A","options":["proud","afraid","tired","bored"],"explanation":"be proud of 为……自豪。"},{"q":"10","answer":"B","options":["lazy","patient","rude","careless"],"explanation":"to be patient 变得有耐心。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U2', 'A Film About a Wood-carver', 'Last week our class watched a (1)____ about a famous wood-carver. The film followed him for a whole (2)____ as he made a single screen by hand. We saw how he chose the wood with great (3)____, touching it and smelling it before cutting. Every tiny flower on the screen was carved with such (4)____ that it looked almost real. The artist said he had spent forty years (5)____ his skill, and he still practised every day. He never (6)____ to be famous; he simply loved his work. When the screen was finished, visitors were (7)____ by its beauty. The film ended with a clear (8)____: crafts like this must be passed on, or they will be (9)____ forever. After watching it, many of us felt a new (10)____ for the artists behind everyday objects.', 135, 2, '[{"q":"1","answer":"C","options":["sandwich","mountain","documentary","ticket"],"explanation":"watched a documentary 看了一部纪录片。"},{"q":"2","answer":"D","options":["song","price","road","year"],"explanation":"for a whole year 整整一年。"},{"q":"3","answer":"A","options":["attention","noise","speed","luck"],"explanation":"with great attention 非常用心。"},{"q":"4","answer":"B","options":["hurry","skill","anger","fear"],"explanation":"such skill that … 技艺高超以至于……。"},{"q":"5","answer":"C","options":["selling","hiding","improving","breaking"],"explanation":"spent years improving his skill 多年精进技艺。"},{"q":"6","answer":"D","options":["refused","failed","began","wanted"],"explanation":"never wanted to be famous 从不想出名。"},{"q":"7","answer":"A","options":["amazed","bored","angry","asleep"],"explanation":"were amazed by its beauty 被美震撼。"},{"q":"8","answer":"B","options":["garden","message","price","season"],"explanation":"a clear message 一个清晰的讯息。"},{"q":"9","answer":"C","options":["found","sold","lost","built"],"explanation":"be lost forever 永远失传。"},{"q":"10","answer":"D","options":["hunger","fear","doubt","respect"],"explanation":"a new respect for … 对……新的敬意。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U2', 'The Pottery Class', 'Mia had always wanted to make things with her own (1)____, so she joined a pottery class in her town. Her teacher, an old potter, first showed her how to prepare the (2)____ before shaping it. "Never (3)____," he warned. "Clay teaches you patience." Mia''s first bowls were uneven and quickly fell (4)____. She felt like giving up, but the potter encouraged her to try (5)____. Little by little, her hands learned to feel the right (6)____ and pressure. After many weeks, she finally made a small cup that did not (7)____ in the oven. She was so (8)____ that she nearly cried. The potter told her that every master had once been a (9)____ like her. From that day on, Mia understood that real skill is built through slow, (10)____ effort.', 132, 2, '[{"q":"1","answer":"A","options":["hands","ears","ships","roads"],"explanation":"make things with her hands 亲手做东西。"},{"q":"2","answer":"B","options":["glass","clay","paper","metal"],"explanation":"prepare the clay 准备陶土。"},{"q":"3","answer":"C","options":["smile","listen","hurry","rest"],"explanation":"Never hurry 切勿心急。"},{"q":"4","answer":"D","options":["asleep","awake","indoors","apart"],"explanation":"fell apart 散开/塌掉。"},{"q":"5","answer":"A","options":["again","never","hardly","almost"],"explanation":"try again 再试一次。"},{"q":"6","answer":"B","options":["noise","shape","price","smell"],"explanation":"the right shape and pressure 合适的形状与力度。"},{"q":"7","answer":"C","options":["sing","float","crack","grow"],"explanation":"did not crack in the oven 在炉中没有裂开。"},{"q":"8","answer":"D","options":["angry","sleepy","bored","happy"],"explanation":"so happy that she nearly cried 高兴到几乎落泪。"},{"q":"9","answer":"A","options":["beginner","winner","teacher","stranger"],"explanation":"had once been a beginner 也曾是新手。"},{"q":"10","answer":"B","options":["lazy","patient","sudden","careless"],"explanation":"slow, patient effort 缓慢而有耐心的努力。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U2', 'A Handmade Gift', 'For my mother''s birthday, I decided to make a (1)____ instead of buying one. I spent two weeks knitting her a warm (2)____ by hand. The work was harder than I had (3)____, and I had to start over twice. My fingers grew tired, but I did not want to (4)____. When she opened the gift, her eyes filled with (5)____. She said that a handmade present meant far more to her than anything from a (6)____. At last I understood why people (7)____ handmade things so much. Each one carries the (8)____ and care of the person who made it. A machine can copy a shape, but it cannot copy real (9)____. That birthday taught me that the best gifts are not the most expensive, but the ones made with (10)____.', 132, 2, '[{"q":"1","answer":"C","options":["road","river","gift","key"],"explanation":"make a gift 做一份礼物。"},{"q":"2","answer":"D","options":["river","ticket","window","scarf"],"explanation":"knitting a warm scarf 织一条暖围巾。"},{"q":"3","answer":"A","options":["expected","forgotten","refused","allowed"],"explanation":"harder than I had expected 比预想的难。"},{"q":"4","answer":"B","options":["win","stop","grow","float"],"explanation":"did not want to stop 不想停下。"},{"q":"5","answer":"C","options":["prices","roads","tears","keys"],"explanation":"eyes filled with tears 眼含泪水。"},{"q":"6","answer":"D","options":["song","garden","season","shop"],"explanation":"anything from a shop 店里买的东西。"},{"q":"7","answer":"A","options":["value","throw","lose","break"],"explanation":"value handmade things 珍视手工之物。"},{"q":"8","answer":"B","options":["noise","love","hurry","fear"],"explanation":"the love and care 爱与用心。"},{"q":"9","answer":"C","options":["metal","glass","feeling","paper"],"explanation":"cannot copy real feeling 无法复制真情。"},{"q":"10","answer":"D","options":["hurry","noise","fear","heart"],"explanation":"made with heart 用心制作。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·对话 At the Photo Exhibition', '外研社版选择性必修第三册 U2 · dialogue', 3, 'Emma: That exhibition of Bill Cunningham''s street photos was wonderful, wasn''t it?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·独白 The Last Clog Maker', '外研社版选择性必修第三册 U2 · passage', 2, 'In a small town lives one of the last traditional clog makers.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·对话 Interview with a Young Photographer', '外研社版选择性必修第三册 U2 · dialogue', 3, 'Host: Today we''re talking with Lily, a young photographer. Lily, how did you start?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·独白 Paper-cutting Comes Back to Life', '外研社版选择性必修第三册 U2 · passage', 2, 'Paper-cutting is one of China''s oldest folk arts.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·对话 In the Clock Room', '外研社版选择性必修第三册 U2 · dialogue', 3, 'Guide: Welcome. This room holds some of the oldest clocks in our museum.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·独白 A Tip for Young Photographers', '外研社版选择性必修第三册 U2 · passage', 2, 'Here is one simple tip for anyone who loves photography or any craft.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Write an Expository Essay about a Person of Craftsmanship(写一篇关于匠心人物的说明文)', 'A Life''s Work', '请用英语写一篇约100词的说明文,介绍一位体现匠心精神的人物(可选王津、梅兰芳或你熟悉的手艺人)。内容包括:① 简要介绍这个人和他/她的工作;② 用具体例子说明他/她的两项可贵品质(如专注、谦逊、坚持);③ 总结他/她带给你的启发。请至少使用两个表语从句(如 This is what… / The reason … is that… / That is why…)。', 'Write an expository essay of about 100 words about a person who shows the spirit of craftsmanship (for example Wang Jin, Mei Lanfang, or a craftworker you know). Include: 1) a short introduction to the person and his or her work; 2) two valuable qualities, each supported by an example; 3) a conclusion about what he or she teaches you. Use at least two predicative clauses (e.g. This is what… / The reason … is that… / That is why…).', '["开头点明人物与主旨(… is a master who … / This essay is about …)","用事实/例子说明品质一(One quality is his devotion. This is what … )","用事实/例子说明品质二(The reason he is respected is that …)","结尾总结启发,运用表语从句(That is why … / This is why I admire him.)"]'::jsonb, 70, 100, 'Wang Jin is a master who repairs antique clocks in the Palace Museum. What makes his work so special is his complete devotion. Day after day, in a quiet courtyard, he cleans every tiny part by hand, and a single large clock may take him months. This is what true craftsmanship means. He is also remarkably modest. The reason he is so respected is that he still calls himself an ordinary worker, even when admirers stop him for photos. From him I have learnt that patience and humility matter far more than fame. That is why I deeply admire people who give their whole lives to one craft.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["What makes his work so special is his complete devotion.","This is what true craftsmanship means.","The reason he is so respected is that he still calls himself an ordinary worker.","That is why I deeply admire people who give their whole lives to one craft."]'::jsonb, '[{"wrong":"The reason he is respected is because he is modest.","correct":"The reason he is respected is that he is modest.","note":"「The reason … is ____」后只能用 that,不能用 because。"},{"wrong":"This is the reason makes his work special.","correct":"This is what makes his work special.","note":"从句缺主语,表语从句用 what 在句中作主语。"},{"wrong":"That is the why I admire him.","correct":"That is why I admire him.","note":"why 引导表语从句,前面不加 the。"}]'::jsonb, '【匠心人物说明文结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective3', 'U2', '{"title":"表语从句·连接词 what / that / why / where / how / when / because / whether 速查","intro":"系动词(be/seem/look 等)后面、用来说明主语「是什么」的从句叫表语从句。判断口诀:从句缺主语/宾语 → 用 what;从句完整、只起连接 → 用 that;从句缺状语 → 按意义选 why/where/how/when;表是非选择 → whether。","table":{"headers":["连接词","什么时候用 / 例句"],"rows":[["what","从句缺主语或宾语:This is what makes them special.(缺主语)"],["that","从句完整、不缺成分:The truth is that he never gave up."],["why","从句缺原因状语:That is why he is admired."],["where","从句缺地点状语:A small shop was where he ate every day."],["how","从句缺方式状语:Practice is how he mastered the craft."],["when","从句缺时间状语:Dawn was when the light was best."],["because","「This is ____」后接原因从句:This is because he refused all gifts."],["whether","表是非选择:The question is whether the clock can be fixed."]]},"specialRules":[{"rule":"「The reason … is ____」后只能用 that,绝不能用 because","mark":"The reason is that …(√) / The reason is because …(×)"},{"rule":"what 在从句里要充当成分(主语或宾语);that 在从句里不作任何成分","mark":"what makes …(what=主语) / that he won(that 不作成分)"},{"rule":"「This is because …」表原因;「This is why …」表结果,方向相反别混","mark":"病了→This is why he didn''t come;没来→This is because he was ill"},{"rule":"表语从句表「是否」用 whether,不用 if","mark":"The point is whether …(√) / is if …(×)"}],"why":["表语从句就是把一个句子整体放在 be 之后当「表语」。连接词的选择只看一件事:这个从句里缺什么——缺主/宾用 what,缺状语按意义用 why/where/how/when,什么都不缺就用 that。"],"gaokaoPoints":["what 与 that 的辨析(从句是否缺主语/宾语)是语法填空与改错的高频考点。","「the reason … is that(not because)」是经典送分陷阱,务必记牢。","why/where/how/when 引导表语从句时,前面不加 the(That is why,不是 That is the why)。"],"examVsReal":[{"exam":"The reason he is respected is that he is modest.(考试)","real":"He''s respected because he''s modest.","note":"考试用表语从句 that;日常口语直接用 because 引出原因状语从句更自然。"},{"exam":"This is what makes them so special.(考试)","real":"That''s the special thing about them.","note":"考试爱考 what 引导的表语从句;口语常换成名词短语,显得更轻松。"}]}'::jsonb, 'fltrp');
